from typing import Dict

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.components.du.du import Du
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.l3_call_cloud import make_l3_call_on_each_du_cell_if_requested


def general_siso_auto_cloud_recommissioning(testing_env: TestingEnv,
                                            online_param_dist_name: str = 'MRBTS-{}/MNL-1',
                                            online_param_name: str = 'timeZone',
                                            online_param_value: str = '(GMT+1) Eire',
                                            offline_param_dist_name: str = 'MRBTS-{}/NRBTS-{}/NRCELL-1',
                                            offline_param_name: str = 'actIncreasedFdmUsersPerSlot',
                                            offline_param_value: str = 'false',
                                            incorrect_param_dist_name: str = 'MRBTS-{}/NRBTS-{}/NRCELL-1',
                                            incorrect_param_name: str = 'pMaxNROwnCell',
                                            incorrect_param_value: str = '40',
                                            throughputs: Dict = None,
                                            ue_network_modes: Dict[str, str] = None):
    """
    Based on:
    QC Test ID: 1155
    QC Test Name: [2.0] Manual_SiSo_CM_Recommissioning

    Should report to:
    QC Test ID: 84003
    QC Test Name: General_SiSo_Auto_Cloud_Recommissioning

    Online recommissioning - parameter change which doesn't require DU reset
    Offline recommissioning - parameter change which requires DU reset
    Incorrect recommissioning - parameter change with incorrect value which results in error

    :param testing_env: testing environment prepared for this test case
    :param online_param_dist_name: dist name of managed object under which parameter for online recommissioning is present;
                                   defaults to 'MRBTS-{}/MNL-1'
    :param online_param_name: name of parameter for online recommissioning; defaults to 'timeZone'
    :param online_param_value: value of parameter for online recommissioning; defaults to '(GMT+1) Eire'
    :param offline_param_dist_name: dist name of managed object under which parameter for offline recommissioning is present;
                                    defaults to 'MRBTS-{}/NRBTS-{}/NRCELL-1'
    :param offline_param_name: name of parameter for offline recommissioning; defaults to 'actIncreasedFdmUsersPerSlot'
    :param offline_param_value: value of parameter for offline recommissioning; defaults to 'false'
    :param incorrect_param_dist_name: dist name of managed object under which parameter for incorrect recommissioning is present;
                                      defaults to 'MRBTS-{}/NRBTS-{}/NRCELL-1'
    :param incorrect_param_name: name of parameter for incorrect recommissioning; defaults to 'pMaxNROwnCell'
    :param incorrect_param_value: value of parameter for incorrect recommissioning; defaults to '40'
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec},
                                       'deviation': '90%'}}
                        defaults to None (L3 call will not be performed)
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             defaults to None (network mode will not be changed on any UE)
    """
    bts = testing_env.btss[0]
    caller = testing_env.caller
    errors = testing_env.errors
    output_dir_path = testing_env.output_dir_path
    params_initial_state = {}
    testing_env.variables.set(name='params_initial_state',
                              value=params_initial_state)

    for du in bts.dus:
        _check_online_recommissioning(du,
                                      params_initial_state,
                                      online_param_dist_name,
                                      online_param_name,
                                      online_param_value,
                                      caller,
                                      throughputs,
                                      ue_network_modes,
                                      output_dir_path,
                                      errors)
        _check_offline_recommissioning(du,
                                       params_initial_state,
                                       offline_param_dist_name,
                                       offline_param_name,
                                       offline_param_value,
                                       caller,
                                       throughputs,
                                       ue_network_modes,
                                       output_dir_path,
                                       errors)
        _check_incorrect_recommissioning(du,
                                         params_initial_state,
                                         incorrect_param_dist_name,
                                         incorrect_param_name,
                                         incorrect_param_value,
                                         errors)

    errors.check()


def teardown_for_general_siso_auto_cloud_recommissioning(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors
    params_initial_state = testing_env.variables.get(name='params_initial_state')

    for du in bts.dus:
        try:
            params_initial_state_for_du = [params for params in params_initial_state[du.name].values()]
            du.check_if_reachable(timeout=600)
            _allow_alarms_related_to_du_reset(du)
            du.config.set_many(params_values=params_initial_state_for_du,
                               wait=False)
            du.check_if_reachable(delay=60,
                                  timeout=600)
            du.check_state(state='on_air',
                           timeout=720)
            _disallow_alarms_related_to_du_reset(du)
        except ResultError as exc:
            errors.add_from_exception(exc=exc)


@pretty_log
def _check_online_recommissioning(du,
                                  params_initial_state,
                                  online_param_dist_name,
                                  online_param_name,
                                  online_param_value,
                                  caller,
                                  throughputs,
                                  ue_network_modes,
                                  output_dir_path,
                                  errors):
    try:
        _store_initial_parameter_value(du, params_initial_state, online_param_dist_name, online_param_name)
        _perform_online_recommissioning(du, online_param_dist_name, online_param_name, online_param_value)
        _check_parameter_value(du, online_param_dist_name, online_param_name, online_param_value)
        make_l3_call_on_each_du_cell_if_requested(du=du,
                                                  caller=caller,
                                                  throughputs=throughputs,
                                                  ue_network_modes=ue_network_modes,
                                                  logs_path=output_dir_path,
                                                  errors=errors)
    except ResultError as exc:
        errors.add(error_type=f'Error during online recommissioning on {du.name}',
                   error_msg=str(exc))


@pretty_log
def _check_offline_recommissioning(du,
                                   params_initial_state,
                                   offline_param_dist_name,
                                   offline_param_name,
                                   offline_param_value,
                                   caller,
                                   throughputs,
                                   ue_network_modes,
                                   output_dir_path,
                                   errors):
    try:
        _store_initial_parameter_value(du, params_initial_state, offline_param_dist_name, offline_param_name)
        _perform_offline_recommissioning(du, offline_param_dist_name, offline_param_name, offline_param_value)
        _check_parameter_value(du, offline_param_dist_name, offline_param_name, offline_param_value)
        make_l3_call_on_each_du_cell_if_requested(du=du,
                                                  caller=caller,
                                                  throughputs=throughputs,
                                                  ue_network_modes=ue_network_modes,
                                                  logs_path=output_dir_path,
                                                  errors=errors)
    except ResultError as exc:
        errors.add(error_type=f'Error during offline recommissioning on {du.name}',
                   error_msg=str(exc))


@pretty_log
def _check_incorrect_recommissioning(du,
                                     params_initial_state,
                                     incorrect_param_dist_name,
                                     incorrect_param_name,
                                     incorrect_param_value,
                                     errors):
    try:
        _store_initial_parameter_value(du, params_initial_state, incorrect_param_dist_name, incorrect_param_name)
        _check_whether_recommissioning_is_impossible(du, incorrect_param_dist_name, incorrect_param_name, incorrect_param_value)
        _check_parameter_value(du, incorrect_param_dist_name, incorrect_param_name, params_initial_state[du.name][incorrect_param_name]['value'])
    except ResultError as exc:
        errors.add(error_type=f'Error during incorrect recommissioning on {du.name}',
                   error_msg=str(exc))


@pretty_log
def _store_initial_parameter_value(du: Du, params_initial_state: Dict, param_dist_name: str, param_name: str):
    param_value = du.config.get(dist_name=param_dist_name,
                                param=param_name)

    if du.name not in params_initial_state:
        params_initial_state[du.name] = {}

    params_initial_state[du.name][param_name] = {'dist_name': param_dist_name,
                                                 'param': param_name,
                                                 'value': param_value}


@pretty_log
def _perform_online_recommissioning(du: Du, param_dist_name: str, param_name: str, param_value: str):
    du.config.set(dist_name=param_dist_name,
                  param=param_name,
                  value=param_value)
    du.check_if_reachable(delay=10)
    du.check_state(state='on_air')


@pretty_log
def _perform_offline_recommissioning(du: Du, param_dist_name: str, param_name: str, param_value: str):
    _allow_alarms_related_to_du_reset(du)
    du.config.set(dist_name=param_dist_name,
                  param=param_name,
                  value=param_value,
                  wait=False)
    du.check_if_unreachable(timeout=180)
    du.check_if_reachable(delay=60,
                          timeout=600)
    du.check_state(state='commissioned',
                   timeout=300)
    du.check_state(state='on_air',
                   timeout=600)
    _disallow_alarms_related_to_du_reset(du)


@pretty_log
def _check_whether_recommissioning_is_impossible(du: Du, param_dist_name: str, param_name: str, param_value: str):
    du.config.set_and_expect_error(dist_name=param_dist_name,
                                   param=param_name,
                                   value=param_value)
    du.check_state(state='on_air')


@pretty_log
def _check_parameter_value(du: Du, param_dist_name: str, param_name: str, expected_param_value: str):
    current_param_value = du.config.get(dist_name=param_dist_name,
                                        param=param_name)
    if current_param_value != expected_param_value:
        raise ResultError(f'On {du.name} parameter {param_dist_name} {param_name} was expected to have {expected_param_value} value, '
                          f'but it was {current_param_value}')


def _allow_alarms_related_to_du_reset(du: Du):
    du.allow_alarm(fault_id='4592',
                   fault_name='BTS Reset Cause')
    du.cu.allow_alarm(fault_id='7104',
                      fault_name='Matching ServedCell not found over F1-C')


def _disallow_alarms_related_to_du_reset(du: Du):
    du.disallow_alarm(fault_id='4592',
                      fault_name='BTS Reset Cause')
    du.cu.disallow_alarm(fault_id='7104',
                         fault_name='Matching ServedCell not found over F1-C')
